import{_ as t,c as a,o as i,al as s}from"./chunks/framework.CT7RwC5a.js";const _=JSON.parse('{"title":"使用 ROS 2 的多载具模拟","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ros2/multi_vehicle.md","filePath":"zh/ros2/multi_vehicle.md"}'),d={name:"zh/ros2/multi_vehicle.md"};function c(o,e,l,n,h,r){return i(),a("div",null,e[0]||(e[0]=[s('<h1 id="使用-ros-2-的多载具模拟" tabindex="-1">使用 ROS 2 的多载具模拟 <a class="header-anchor" href="#使用-ros-2-的多载具模拟" aria-label="Permalink to &quot;使用 ROS 2 的多载具模拟&quot;">​</a></h1><p><a href="./../middleware/uxrce_dds.html">XRCE-DDS</a>支持多个客户端通过 UDP 协议连接到同一个代理。 这在模拟中特别有用，因为只有一个代理需要启动。</p><h2 id="设置和要求" tabindex="-1">设置和要求 <a class="header-anchor" href="#设置和要求" aria-label="Permalink to &quot;设置和要求&quot;">​</a></h2><p>唯一的要求是</p><ul><li>能够在不依赖 ROS 2 的情况下，使用所需的仿真器(<a href="./../sim_gazebo_gz/multi_vehicle_simulation.html">Gazebo</a>, <a href="./../sim_gazebo_classic/multi_vehicle_simulation.html#multiple-vehicle-with-gazebo-classic">Gazebo Classic</a>, <a href="./../sim_flightgear/multi_vehicle.html">FlightGear</a> and <a href="./../sim_jmavsim/multi_vehicle.html">JMAVSim</a>)运行多载具模拟 <a href="./../simulation/multi-vehicle-simulation.html">multi-vehicle simulation</a> 。</li><li>能够在单一载具模拟中使用 <a href="./../ros2/user_guide.html">ROS 2</a></li></ul><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>在模拟中，每个 PX4 实例都会获得一个唯一的<code>px4_instance</code>编号，编号从<code>0</code>开始。 该值用于为 <a href="./../advanced_config/parameter_reference.html#UXRCE_DDS_KEY">UXRCE_DDS_KEY</a>分配一个唯一值：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">参数设置UXRCE_DDS_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $((</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">px4_instance+1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>通过这种方式， <code>UXRCE_DDS_KEY</code> 将始终与 [MAV_SYS_ID] 保持一致(../advanced_config/parameter_reference.md#MAV_SYS_ID)</p></div><p>此外，当 <code>px4_instance</code> 大于 0 时，会添加一个格式为 <code>px4_$px4_instance</code> 的唯一 ROS 2<a href="./../middleware/uxrce_dds.html#customizing-the-namespace">namespace prefix</a>：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uxrce_dds_ns</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-n px4_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$px4_instance</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>环境变量<code>PX4_UXRCE_DDS_NS</code> 若已设置，将覆盖上文所述的命名空间行为。</p></div><p>第一个实例(<code>px4_instance=0</code>)没有额外的命名空间，此举是为了与真实载具上 xrce-dds 客户端的默认行为保持一致。 这种不匹配可以通过手动使用 <code>PX4_UXRCE_DDS_NS</code> 来修复，或者通过从索引 <code>1</code> 中添加车辆而不是 <code>0</code> (这是Gazebo Classic的 <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/simulation/gazebo-classic/sitl_multiple_run.sh" target="_blank" rel="noreferrer">sitl_multiple_run.sh</a> 的默认行为)。</p><p>模拟中的默认客户端配置概述如下：</p><table tabindex="0"><thead><tr><th><code>PX4_UXRCE_DDS_NS</code></th><th><code>px4_instance</code></th><th><code>UXRCE_DDS_KEY</code></th><th>client namespace</th></tr></thead><tbody><tr><td>not provided</td><td>0</td><td><code>px4_instance+1</code></td><td>无</td></tr><tr><td>provided</td><td>0</td><td><code>px4_instance+1</code></td><td><code>PX4_UXRCE_DDS_NS</code></td></tr><tr><td>not provided</td><td>&gt; 0</td><td><code>px4_instance+1</code></td><td><code>px4_${px4_instance}</code></td></tr><tr><td>provided</td><td>&gt; 0</td><td><code>px4_instance+1</code></td><td><code>PX4_UXRCE_DDS_NS</code></td></tr></tbody></table><h2 id="调整-target-system-值" tabindex="-1">调整 <code>target_system</code> 值 <a class="header-anchor" href="#调整-target-system-值" aria-label="Permalink to &quot;调整 `target_system` 值&quot;">​</a></h2><p>PX4 只在他们的 <code>target_system</code> 字段为 0<code>(路由通信) 或与</code>MAV_SYS_ID<code> 一致时，才接受[VehicleCommand](../msg_docs/VehicleCommand.md)。 在所有其他情况下，信息都被忽视。 因此，当 ROS 2 节点需向 PX4 发送</code>VehicleCommand<code>消息时，必须确保消息中填写了合适的</code>target_system`字段值。</p><p>例如，若你想向 <code>px4_instance=2</code> 的第三台飞行器发送指令，则需要在所有<code>VehicleCommand</code>消息中设置 <code>target_system=3</code>。</p>',18)]))}const m=t(d,[["render",c]]);export{_ as __pageData,m as default};
